package com.olaf.rereminder.utils

import android.content.ContentResolver
import android.content.Context
import android.net.Uri
import com.olaf.rereminder.R

/**
 * The alarm sounds bundled with the app — soft, original tones generated by
 * `tools/generate_sounds.py` (see `docs/SOUNDS.md` for their license).
 *
 * Only [id] is ever stored, never the resource URI: resource ids change from build to build.
 * Referencing [rawRes] from code also keeps resource shrinking from dropping the files.
 */
enum class GentleSound(val id: String, val labelRes: Int, val rawRes: Int) {
    SOFT_CHIME("soft_chime", R.string.sound_soft_chime, R.raw.alarm_soft_chime),
    GENTLE_BELL("gentle_bell", R.string.sound_gentle_bell, R.raw.alarm_gentle_bell),
    CALM_TONE("calm_tone", R.string.sound_calm_tone, R.raw.alarm_calm_tone),
    ;

    fun uri(context: Context): Uri = Uri.Builder()
        .scheme(ContentResolver.SCHEME_ANDROID_RESOURCE)
        .authority(context.packageName)
        .appendPath(rawRes.toString())
        .build()

    companion object {
        val DEFAULT = SOFT_CHIME

        /** Unknown or missing ids (a setting from a later version, say) fall back to [DEFAULT]. */
        fun fromId(id: String?): GentleSound = entries.firstOrNull { it.id == id } ?: DEFAULT
    }
}
